def _owner_condition(table: str, prefix: str = "OLD.") -> str:
    if table in {"mail_attempts", "mail_bounces"}:
        return (
            "EXISTS(SELECT 1 FROM mail_deliveries d JOIN privacy_erasures e ON e.user_id=d.user_id "
            f"WHERE d.id={prefix}delivery_id)"
        )
    if table == "report_version_forecasts":
        return (
            "EXISTS(SELECT 1 FROM user_report_versions v "
            "JOIN privacy_erasures e ON e.user_id=v.user_id "
            f"WHERE v.id={prefix}report_version_id)"
        )
    if table == "report_build_inputs":
        return (
            "EXISTS(SELECT 1 FROM jobs j JOIN privacy_erasures e ON e.user_id=j.user_id "
            f"WHERE j.id={prefix}job_id)"
        )
    return f"EXISTS(SELECT 1 FROM privacy_erasures e WHERE e.user_id={prefix}user_id)"


